from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    """Return x squared."""
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing the squares in parallel
    on a thread pool. The result preserves the order of xs."""
    with ThreadPoolExecutor() as ex:
        return list(ex.map(square, xs))


def test_square() -> None:
    assert square(0) == 0
    assert square(3) == 9
    assert square(-4) == 16


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_preserves_order() -> None:
    assert squares([3, 1, 2]) == [9, 1, 4]


def test_squares_negatives() -> None:
    assert squares([-2, 0, 5]) == [4, 0, 25]


def test_squares_large_input() -> None:
    xs = list(range(10_000))
    assert squares(xs) == [x * x for x in xs]


def test_squares_does_not_mutate_input() -> None:
    xs = [1, 2, 3]
    squares(xs)
    assert xs == [1, 2, 3]
